        "psr-4": {
            "AmazonSQSSubscriber\\": "src/"
        }
    }
}
```

 10. Run `composer dump-autoload` to generate the autoloader.

```bash
composer dump-autoload
```

 11. Create a `config.php` file to store the AWS credentials and database connection details.

```php
<?php

return [
    'aws' => [
        'region' => 'us-west-2',
        'accessKey' => 'your-access-key',
        'secretKey' => 'your-secret-key',
    ],
    'database' => [
        'host' => 'localhost',
        'port' => '3306',
        'dbname' => 'your-database-name',
        'username' => 'your-database-username',
        'password' => 'your-database-password',
    ],
];
```

 12. Create an `index.php` file to bootstrap the application.

```php
<?php

require_once __DIR__ . '/vendor/autoload.php';

$config = require __DIR__ . '/config.php';

$sqsClient = new SQSClient($config['aws']['region'], $config['aws']['accessKey'], $config['aws']['secretKey']);
